B=[]
def b(z,i,name,latin,syn,reg,loc,desc,fn,clin):B.append((z,i,name,latin,syn,reg,loc,desc,fn,clin))
L='lower-limb';U='upper-limb'
b('(Iliopectineal bursa).l','iliopectineal-bursa','Iliopectineal bursa','Bursa iliopectinea',['iliopsoas bursa','subtendinous bursa of iliacus'],L,'In front of the hip joint, between the iliopsoas tendon and the front of the hip capsule.','A large synovial bursa that sometimes communicates with the hip joint cavity.','Reduces friction between the iliopsoas tendon and the pelvis and hip capsule.','Inflammation (iliopsoas bursitis) causes groin pain and snapping at the front of the hip.')
b('Anserine bursa.l','anserine-bursa','Anserine bursa','Bursa anserina',['pes anserinus bursa'],L,'On the inner side of the upper tibia just below the knee, beneath the pes anserinus tendons.','A bursa between the tendons of sartorius, gracilis and semitendinosus and the tibia and medial collateral ligament.','Reduces friction as the tendons glide over the bone and ligament.','Anserine bursitis causes pain on the inner side of the knee, common in runners and in people with knee arthritis.')
b('Bicipitoradial bursa.l','bicipitoradial-bursa','Bicipitoradial bursa','Bursa bicipitoradialis',['radiobicipital bursa'],U,'In front of the elbow, between the distal biceps tendon and the radial tuberosity.','A small bursa that cushions the biceps tendon as it wraps round the radius during forearm rotation.','Reduces friction on the biceps tendon at its insertion.','Inflammation or distal biceps tendon injury can cause pain in front of the elbow.')
b('Coracobrachial bursa.l','coracobrachial-bursa','Coracobrachial bursa','Bursa musculi coracobrachialis',[],U,'Below the coracoid process at the front of the shoulder, between coracobrachialis and the subscapularis tendon.','A small bursa in the front of the shoulder.','Reduces friction between coracobrachialis and the subscapularis tendon.','Rarely a source of pain on its own; inflammation is part of anterior shoulder pain.')
b('Deep infrapatellar bursa.l','deep-infrapatellar-bursa','Deep infrapatellar bursa','Bursa infrapatellaris profunda',[],L,'Below the kneecap, between the patellar ligament and the upper tibia.','A small bursa behind the patellar ligament, in front of the tibia.','Cushions the patellar ligament against the tibia during knee movement.','Bursitis causes pain below the kneecap, often with kneeling or jumping.')
b('Inferior subtendinous bursa of biceps femoris muscle.l','inferior-subtendinous-bursa-of-biceps-femoris','Inferior subtendinous bursa of biceps femoris','Bursa subtendinea inferior musculi bicipitis femoris',[],L,'On the outer side of the knee, between the biceps femoris tendon and the fibular collateral ligament.','A small bursa at the lower end of the biceps femoris tendon.','Reduces friction between the tendon and the fibular collateral ligament.','Inflammation can cause pain on the outer side of the knee.')
b('Intermuscular gluteal bursae.l','intermuscular-gluteal-bursae','Intermuscular gluteal bursae','Bursae intermusculares musculorum gluteorum',[],L,'Between the gluteal muscles of the buttock.','Several small bursae lying between neighbouring gluteal muscles.','Let the gluteal muscles slide over each other.','Seldom identified separately; may add to deep buttock pain when inflamed.')
b('Lateral subtendinous bursa of gastrocnemius muscle.l','lateral-subtendinous-bursa-of-gastrocnemius','Lateral subtendinous bursa of gastrocnemius','Bursa subtendinea musculi gastrocnemii lateralis',[],L,'Behind the knee, between the lateral head of gastrocnemius and the back of the joint capsule.','A bursa beneath the tendon of the lateral head of gastrocnemius.','Reduces friction between the tendon and the femur and capsule.','May communicate with the knee joint and take part in popliteal swellings.')
b('Medial subtendinous bursa of gastrocnemius muscle.l','medial-subtendinous-bursa-of-gastrocnemius','Medial subtendinous bursa of gastrocnemius','Bursa subtendinea musculi gastrocnemii medialis',[],L,'Behind the knee, between the medial head of gastrocnemius and the back of the joint capsule.','A bursa beneath the tendon of the medial head of gastrocnemius, usually joined to the knee joint cavity and to the semimembranosus bursa.','Reduces friction between the tendon and the capsule.','Distension forms a popliteal (Baker) cyst, a swelling behind the knee.')
b('Sciatic bursa of gluteus maximus muscle.l','sciatic-bursa-of-gluteus-maximus','Sciatic bursa of gluteus maximus','Bursa ischiadica musculi glutei maximi',['ischial bursa'],L,'Over the ischial tuberosity, between gluteus maximus and the bone.','A bursa that cushions the sitting bone beneath the lower edge of gluteus maximus.','Reduces friction between the muscle and the ischial tuberosity.','Prolonged sitting can inflame it (ischial bursitis, sometimes called weaver\'s bottom).')
b('Sciatic bursa of obturator internus.l','sciatic-bursa-of-obturator-internus','Sciatic bursa of obturator internus','Bursa ischiadica musculi obturatorii interni',[],L,'At the lesser sciatic notch, where the obturator internus tendon turns round the ischium.','A bursa between the tendon of obturator internus and the ischium.','Lets the tendon glide as it turns round the bone.','Inflammation may add to deep pelvic and buttock pain.')
b('Semimembranosus bursa.l','semimembranosus-bursa','Semimembranosus bursa','Bursa musculi semimembranosi',[],L,'Behind the knee on the inner side, between the semimembranosus tendon and the medial head of gastrocnemius.','A bursa that often communicates with the knee joint.','Reduces friction between the semimembranosus tendon and neighbouring structures.','A common site of popliteal (Baker) cyst formation.')
b('Subacromial bursa.l','subacromial-bursa','Subacromial bursa','Bursa subacromialis',[],U,'Beneath the acromion, above the supraspinatus tendon and the head of the humerus.','A large bursa between the acromion and deltoid above and the rotator cuff below; it is often continuous with the subdeltoid bursa.','Lets the rotator cuff slide beneath the acromion when the arm is raised.','Subacromial bursitis and impingement are common causes of shoulder pain on lifting the arm.')
b('Subcutaneous acromial bursa.l','subcutaneous-acromial-bursa','Subcutaneous acromial bursa','Bursa subcutanea acromialis',[],U,'On top of the acromion, between the skin and the bone.','A small inconstant bursa over the tip of the shoulder.','Cushions the skin over the acromion.','Can be inflamed by pressure from straps or carrying loads.')
b('Subcutaneous bursa of lateral malleolus.l','subcutaneous-bursa-of-lateral-malleolus','Subcutaneous bursa of the lateral malleolus','Bursa subcutanea malleoli lateralis',[],L,'Over the outer ankle bone, between skin and bone.','A bursa over the lateral malleolus of the fibula.','Cushions the skin over the bony prominence.','Pressure from footwear can inflame it.')
b('Subcutaneous bursa of medial malleolus.l','subcutaneous-bursa-of-medial-malleolus','Subcutaneous bursa of the medial malleolus','Bursa subcutanea malleoli medialis',[],L,'Over the inner ankle bone, between skin and bone.','A bursa over the medial malleolus of the tibia.','Cushions the skin over the bony prominence.','Pressure from footwear can inflame it.')
b('Subcutaneous bursa of tuberosity of tibia.l','subcutaneous-bursa-of-tibial-tuberosity','Subcutaneous bursa of the tibial tuberosity','Bursa subcutanea tuberositatis tibiae',[],L,'Over the bony bump below the kneecap, between skin and bone.','A bursa in front of the tibial tuberosity.','Cushions the skin over the tuberosity.','Kneeling can inflame it.')
b('Subcutaneous calcaneal bursa.l','subcutaneous-calcaneal-bursa','Subcutaneous calcaneal bursa','Bursa subcutanea calcanea',[],L,'At the back of the heel, between the skin and the Achilles tendon insertion.','A bursa between skin and the lower Achilles tendon.','Cushions the skin over the back of the heel.','Pressure from shoes causes a painful swelling, associated with Haglund deformity.')
b('Subcutaneous infrapatellar bursa.l','subcutaneous-infrapatellar-bursa','Subcutaneous infrapatellar bursa','Bursa subcutanea infrapatellaris',[],L,'In front of the patellar ligament below the kneecap, beneath the skin.','A bursa between the skin and the patellar ligament.','Cushions the skin over the front of the knee below the kneecap.','Kneeling can inflame it (sometimes called clergyman\'s knee).')
b('Subcutaneous prepatellar bursa.l','subcutaneous-prepatellar-bursa','Subcutaneous prepatellar bursa','Bursa subcutanea prepatellaris',[],L,'In front of the kneecap, between skin and the deep fascia.','The most superficial of the prepatellar bursae.','Lets the skin move over the kneecap.','Inflammation with kneeling causes housemaid\'s knee.')
b('Subfacial prepatellar bursa.l','subfascial-prepatellar-bursa','Subfascial prepatellar bursa','Bursa subfascialis prepatellaris',[],L,'In front of the kneecap, beneath the deep fascia.','A middle prepatellar bursa lying below the fascia and above the quadriceps tendon.','Lets the fascia and tendon move over the kneecap.','May be inflamed with the other prepatellar bursae.')
b('Subtendinous prepatellar bursa.l','subtendinous-prepatellar-bursa','Subtendinous prepatellar bursa','Bursa subtendinea prepatellaris',[],L,'In front of the kneecap, beneath the quadriceps tendon.','The deepest prepatellar bursa, close to the kneecap.','Lets the quadriceps tendon glide over the patella.','May be inflamed with the other prepatellar bursae.')
b('Subcutaneous trochanteric bursa.l','subcutaneous-trochanteric-bursa','Subcutaneous trochanteric bursa','Bursa subcutanea trochanterica',[],L,'Over the greater trochanter at the side of the hip, between skin and fascia.','A superficial bursa over the bony point of the hip.','Cushions the skin over the greater trochanter.','Lying on the side or direct pressure can inflame it.')
b('Subdeltoid bursa.l','subdeltoid-bursa','Subdeltoid bursa','Bursa subdeltoidea',[],U,'Below the deltoid, over the head of the humerus and rotator cuff.','A bursa beneath the deltoid that is usually continuous with the subacromial bursa.','Lets the deltoid slide over the rotator cuff and humerus.','Inflammation contributes to shoulder pain and impingement.')
b('Subtendinous bursa of infraspinatus muscle.l','subtendinous-bursa-of-infraspinatus','Subtendinous bursa of infraspinatus','Bursa subtendinea musculi infraspinati',[],U,'At the back of the shoulder, between the infraspinatus tendon and the joint capsule.','A small bursa that may communicate with the shoulder joint.','Reduces friction between the tendon and the capsule.','Seldom a separate cause of symptoms.')
b('Subtendinous bursa of teres major muscle.l','subtendinous-bursa-of-teres-major','Subtendinous bursa of teres major','Bursa subtendinea musculi teretis majoris',[],U,'On the upper inner humerus, between the teres major tendon and the bone.','A small bursa at the insertion of teres major.','Reduces friction between the tendon and the humerus.','Seldom a separate cause of symptoms.')
b('Subtendinous bursa of tibialis anterior.l','subtendinous-bursa-of-tibialis-anterior','Subtendinous bursa of tibialis anterior','Bursa subtendinea musculi tibialis anterioris',[],L,'At the front of the ankle and foot, between the tibialis anterior tendon and the medial cuneiform.','A small bursa at the insertion of tibialis anterior.','Reduces friction between the tendon and the bone.','Can be inflamed by tight footwear or overuse.')
b('Subtendinous bursa of triceps brachii muscle.l','subtendinous-bursa-of-triceps-brachii','Subtendinous bursa of triceps brachii','Bursa subtendinea musculi tricipitis brachii',['deep olecranon bursa'],U,'At the back of the elbow, between the triceps tendon and the olecranon.','A bursa under the triceps tendon, just above its insertion on the olecranon.','Reduces friction between the tendon and the olecranon.','Inflammation causes pain at the back of the elbow with leaning or overuse.')
b('Subtendinous calcaneal bursa.l','subtendinous-calcaneal-bursa','Subtendinous calcaneal bursa','Bursa subtendinea calcanea',['retrocalcaneal bursa'],L,'At the back of the heel, between the Achilles tendon and the heel bone.','A bursa in front of the lower Achilles tendon, in front of its insertion.','Reduces friction between the Achilles tendon and the calcaneus.','Retrocalcaneal bursitis causes pain at the back of the heel, common in runners and with Haglund deformity.')
b('Superior bursa of biceps femoris muscle.l','superior-bursa-of-biceps-femoris','Superior bursa of biceps femoris','Bursa superior musculi bicipitis femoris',[],L,'Behind the thigh above the knee, between the biceps femoris and semimembranosus tendons.','A bursa between the tendons of two hamstring muscles near the back of the knee.','Reduces friction between neighbouring hamstring tendons.','Seldom a separate cause of symptoms.')
b('Suprapatellar bursa.l','suprapatellar-bursa','Suprapatellar bursa','Bursa suprapatellaris',['quadriceps bursa'],L,'Above the kneecap, between the quadriceps tendon and the femur.','A large pouch that is an extension of the knee joint cavity.','Lets the quadriceps tendon slide over the lower femur as the knee bends.','Knee joint effusion collects here and shows as swelling above the kneecap.')
b('Trochanteric bursa of gluteus maximus muscle.l','trochanteric-bursa-of-gluteus-maximus','Trochanteric bursa of gluteus maximus','Bursa trochanterica musculi glutei maximi',[],L,'At the side of the hip, between gluteus maximus and the greater trochanter.','The largest bursa of the greater trochanter region, beneath gluteus maximus.','Reduces friction between the gluteus maximus tendon and the greater trochanter.','Trochanteric bursitis is associated with greater trochanteric pain syndrome.')
b('Trochanteric bursa of gluteus medius muscle.l','trochanteric-bursa-of-gluteus-medius','Trochanteric bursa of gluteus medius','Bursa trochanterica musculi glutei medii',[],L,'At the side of the hip, between the gluteus medius tendon and the greater trochanter.','A bursa under the tendon of gluteus medius.','Reduces friction between the tendon and the greater trochanter.','Associated with greater trochanteric pain syndrome.')
b('Trochanteric bursa of gluteus minimus muscle.l','trochanteric-bursa-of-gluteus-minimus','Trochanteric bursa of gluteus minimus','Bursa trochanterica musculi glutei minimi',[],L,'At the front of the greater trochanter, between the gluteus minimus tendon and the bone.','A small bursa beneath the gluteus minimus tendon.','Reduces friction between the tendon and the greater trochanter.','Associated with greater trochanteric pain syndrome.')
